import React from 'react'

const OurLeaders = (props) => {
    return (
        <section className="py-3 mb-3 rounded-3 mx-3">
            {/* Team Section */}
            <div className="container text-center">
                <h2 className="fw-bold mb-3 underline text-color">{props.OurLeaders.Heading}</h2>
                <div className="row justify-content-center g-4">
                    <div className="col-md-3">
                        <div className="card border-0 shadow-sm position-relative text-white">
                            <img
                                src={`${process.env.PUBLIC_URL}/${props.OurLeaders.leader1.image}`}
                                className="card-img"
                                alt="Founder"
                                onError={(e) => {
                                    e.target.onerror = null;
                                    e.target.src = "Img/user.png";
                                }}
                            />
                            <div className="card-img-overlay d-flex flex-column justify-content-end p-3" style={{ background: "linear-gradient(to top, rgba(0,0,0,0.6), transparent)" }}>
                                <h5 className="card-title fw-bold mb-0">{props.OurLeaders.leader1.leaderName}</h5>
                                <p className="mb-0 small">{props.OurLeaders.leader1.designation}</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section >
    )
}

export default OurLeaders;
