import React from 'react'
import Branches from './Branches';
import Foundation from './Foundation';

const Home = (props) => {
  return (
    <>
      <div className="flex-d position-relative py-5">
          <p className="text-color mx-5" style={{ textAlign: "justify", fontWeight: "600", fontSize: "1.1rem" }}>
            {props.Vision}
          </p>
      </div>
      <Branches branches={props.branches}/>
      <Foundation foundation={props.foundation}/>
    </>
  )
}

export default Home;
