import React from 'react'

const Contact = () => {
  return (
    <div className="contact-section py-3">
      <div className="row justify-content-center">
        <div className="col-md-8">
          <h1 className="text-center m-0 fw-bold text-color mb-2">Contact Us</h1>
          <div className="d-flex flex-column p-4 justify-content-center align-items-center">
            <h5 className="text-center mb-4 text-color">Get in Touch with Us</h5>
            <form className="form w-100 rounded-4">
              <div className="input-group rounded-5 my-3">
                <input type="text" className="input rounded-2" />
                <label className="placeholders">Name</label>
              </div>
              <div className="input-group rounded-5 my-3">
                <input type="email" className="input rounded-2" />
                <label className="placeholders">Email</label>
              </div>
              <div className="input-group rounded-5 my-3">
                <textarea className="input rounded-2" rows={5}></textarea>
                <label className="placeholders">Message</label>
              </div>
              <div className="text-center">
                <button type="submit" className="btn bg-color text-white px-4">
                  Submit
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  )
}

export default Contact;
