import React,{useState} from 'react'

const Gallery = (props) => {
    const { Heading, galleryData } = props;
    const [selectedImage, setSelectedImage] = useState(null);

    if (!galleryData || Object.keys(galleryData).length === 0) {
        return (
            <div className="container my-5">
                <h2 className="text-center fw-bold mb-4 text-color">{Heading || "Gallery"}</h2>
                <div className="alert alert-warning text-center rounded-4 shadow-sm">
                    <p>No gallery data available.</p>
                </div>
            </div>
        );
    }
    return (
        <div className="container my-3 pt-4 rounded-5">
            <h1 className="text-center fw-bold mb-3 text-color">
                {Heading || "School Gallery"}
            </h1>

            {Object.keys(galleryData).map((key, index) => {
                const section = galleryData[key];

                return (
                    <div key={index} className="mb-4 border border-dark border-2 rounded-4 shadow-lg" >
                        <h4 className="fw-bold text-center pt-3" style={{color:'#800000'}}>{section.title}</h4>
                        <p className="text-muted text-center">{section.quotes}</p>

                        {/* Centered row */}
                        <div className="row g-3 justify-content-center pb-4 mx-1 rounded-5">
                            {section.images.map((img, idx) => (
                                <div
                                    key={idx}
                                    className="col-10 col-sm-6 col-md-4 col-lg-3 d-flex justify-content-center rounded-5"
                                >
                                    <div
                                        className="card border-0 d-flex justify-content-center align-items-center rounded-5"
                                        style={{
                                            height: "220px",
                                            width: "100%",
                                            maxWidth: "250px",
                                            overflow: "hidden",
                                            cursor: "pointer",
                                            transition: "transform 0.3s ease, box-shadow 0.3s ease",
                                        }}
                                        onClick={()=>setSelectedImage(img)}
                                        onMouseEnter={(e)=>e.currentTarget.style.transform="scale(1.05)"}
                                        onMouseLeave={(e)=>(e.currentTarget.style.transform="scale(1)")}
                                    >
                                        <img
                                            src={img}
                                            alt={`${section.title} ${idx + 1}`}
                                            className="img-fluid"
                                            style={{
                                                maxHeight: "100%",
                                                maxWidth: "100%",
                                                objectFit: "contain",
                                            }}
                                            onError={(e) => (e.target.src = "Img/placeholder.jpg")}
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                );
            })}
            {/* Bootstrap Modal for fullscreen image */}
            <div
                className="modal fade show"
                style={{
                    display: selectedImage ? "block" : "none",
                    backgroundColor: "rgba(0,0,0,0.85)",
                }}
                tabIndex="-1"
                onClick={() => setSelectedImage(null)}
            >
                <div className="modal-dialog modal-dialog-centered modal-fullscreen-sm-down">
                    <div className="modal-content bg-transparent border-0 d-flex justify-content-center align-items-center">
                        {selectedImage && (
                            <img
                                src={selectedImage}
                                alt="Full view"
                                className="img-fluid rounded shadow-lg"
                                style={{
                                    maxHeight: "80vh",
                                    maxWidth: "80vw",
                                    objectFit: "contain",
                                }}
                            />
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

export default Gallery
