import React, { useEffect, useRef } from 'react';
import WriteReviews from './WriteReviews';

const Reviews = (props) => {
    const scrollRef = useRef(null);
    const reviews = props.alumniData?.reviews || [];
    const loopedReviews = [...reviews, ...reviews]; // Duplicate for seamless looping

    useEffect(() => {
        const scrollContainer = scrollRef.current;
        let frame;
        let isRunning = false;

        const speed = 2;

        const loop = () => {
            if (!scrollContainer) return;

            scrollContainer.scrollLeft += speed;

            const half = scrollContainer.scrollWidth / 2;

            if (scrollContainer.scrollLeft >= half) {
                scrollContainer.scrollLeft = 0;
            }

            frame = requestAnimationFrame(loop);
        };

        const start = () => {
            if (!isRunning) {
                isRunning = true;
                frame = requestAnimationFrame(loop);
            }
        };

        const stop = () => {
            isRunning = false;
            cancelAnimationFrame(frame);
        };

        // start animation
        start();

        // stop on hover
        scrollContainer.addEventListener("mouseenter", stop);
        scrollContainer.addEventListener("mouseleave", start);

        // stop on touch
        scrollContainer.addEventListener("touchstart", stop, { passive: true });

        // start again after touch
        scrollContainer.addEventListener("touchend", start, { passive: true });

        return () => {
            stop();
            scrollContainer.removeEventListener("mouseenter", stop);
            scrollContainer.removeEventListener("mouseleave", start);
            scrollContainer.removeEventListener("touchstart", stop);
            scrollContainer.removeEventListener("touchend", start);
        };
    }, []);

    return (
        <section className="container-fluid my-5 justify-content-center">
            <h2 className="fw-bold mb-5 text-center">{props.Heading || "Alumni Reviews"}</h2>
            <div className="scroll-container d-flex gap-3 mx-auto px-2 pb-4 px-sm-3 border-bottom border-dark"
                ref={scrollRef}
                style={{
                    overflowX: "auto",
                    scrollBehavior: "smooth",
                    whiteSpace: "nowrap",
                    cursor: "grab"
                }}
            >
                {loopedReviews.map((review, index) => (
                    <div key={index}
                        className="col-md-5 d-flex align-items-center mx-3"
                        style={{
                            minWidth: "350px",
                            maxWidth: "400px",
                            whiteSpace: "normal"
                        }}
                    >
                        <div className="d-flex flex-column align-items-center justify-content-start me-3" style={{ width: "30%", minWidth:"110px", flexShrink: 0 }}>
                            <img
                                src={`${process.env.PUBLIC_URL}/${review.image}`}
                                alt={`review-${index + 1}`}
                                className="img-fluid rounded me-3"
                                style={{ width: "100%", height: "120px", objectFit: "cover" }}
                            />
                            <p className="mb-1"><b>{review.name}</b></p>
                        </div>
                        <div className="flex">
                            <p className="text-color mb-0 review-text" style={{ textAlign: "justify" }}>{review.text}</p>
                        </div>
                    </div>
                ))}
            </div>
            <WriteReviews />
        </section>
    )
}

export default Reviews;
