import React from 'react'

const Letters = (props) => {
    return (
        <div className="container-fluid my-4">
            <h3 className="text-center mb-3 fw-bold">Letter to Old Students</h3>
            <div className="ratio ratio-4x3 shadow rounded-4">
                <iframe
                    src={`${process.env.PUBLIC_URL}/docs/letter to old students.pdf#zoom=100`}
                    width="100%"
                    height="600px"
                    title="Letter PDF"
                    frameBorder="0"

                    style={{
                        border: "none",
                        borderRadius: "10px",
                        boxShadow: "0 0 10px rgba(0,0,0,0.1)",
                    }}
                ></iframe>
            </div>
        </div>
    )
}

export default Letters;
