import React from 'react'

const OurStory = (props) => {
    return (
        <section className="container py-5 text-center">
            {/* History Section */}
            <h2 className="fw-bold mb-4 underline text-color">{props.OurStory.Heading}</h2>
            <p className="text-muted mx-auto fs-5" style={{ maxWidth: "850px" }} dangerouslySetInnerHTML={{ __html: props.OurStory.paragraph }}>
            </p>
        </section>
    )
}

export default OurStory